# -*- coding: utf-8 -*-
"""ASTERIUS dlc — visible pixel-change click utility for Windows.

The app samples the screen center (with optional offsets) while enabled and
clicks when the sampled pixel changes beyond the configured RGB tolerance.
It is intentionally visible and includes an emergency stop key (Esc).
"""

import argparse
import base64
import io
import json
import os
import random
import sys
import threading
import time
import tkinter as tk
from tkinter import messagebox

import customtkinter as ctk
import keyboard
import pyautogui
from PIL import Image, ImageTk

APP_NAME = "ASTERIUS dlc"
APP_DIR = os.path.join(os.environ.get("APPDATA", os.path.expanduser("~")), "ASTERIUS dlc")
CONFIG_PATH = os.path.join(APP_DIR, "settings.json")
ICON_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "asterius.ico")
LOGO_B64 = ""

THEMES = {
    "Asterius": {"bg": "#0a0506", "card": "#170a0d", "track": "#2c1519", "accent": "#e0143c", "text": "#f2f2f7", "muted": "#99909a"},
    "Prism": {"bg": "#0e0c14", "card": "#181622", "track": "#2a2738", "accent": "#7c5cff", "text": "#f2f2f7", "muted": "#9995a8"},
    "Ocean": {"bg": "#0a1218", "card": "#12202b", "track": "#223442", "accent": "#2fb7ff", "text": "#f2f2f7", "muted": "#91a6b5"},
    "Emerald": {"bg": "#09120e", "card": "#112019", "track": "#1f3629", "accent": "#2ee59d", "text": "#f2f2f7", "muted": "#91a99b"},
    "Gold": {"bg": "#12100a", "card": "#1e1b10", "track": "#38321c", "accent": "#f0b429", "text": "#f2f2f7", "muted": "#aaa18a"},
}

DEFAULTS = {
    "theme": "Asterius", "hotkey": "f6", "stop_key": "esc",
    "tolerance": 15, "offset_x": 0, "offset_y": 0,
    "cooldown_ms": 150, "always_on_top": True,
}

# Keep PyAutoGUI's corner emergency stop enabled.
pyautogui.FAILSAFE = True
pyautogui.PAUSE = 0


def load_logo(size=None):
    raw = base64.b64decode(LOGO_B64)
    image = Image.open(io.BytesIO(raw)).convert("RGBA")
    if size:
        image.thumbnail((size, size), Image.Resampling.LANCZOS)
    return image


def make_icon():
    image = load_logo((256, 256))
    image.save(ICON_PATH, format="ICO", sizes=[(256, 256), (128, 128), (64, 64), (32, 32), (16, 16)])
    print(f"Created: {ICON_PATH}")


def read_settings():
    cfg = DEFAULTS.copy()
    try:
        with open(CONFIG_PATH, "r", encoding="utf-8") as f:
            saved = json.load(f)
        cfg.update({k: v for k, v in saved.items() if k in DEFAULTS})
    except (OSError, ValueError, TypeError):
        pass
    if cfg["theme"] not in THEMES:
        cfg["theme"] = "Asterius"
    return cfg


def save_settings(cfg):
    os.makedirs(APP_DIR, exist_ok=True)
    try:
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
    except OSError as exc:
        print(f"Could not save settings: {exc}")


class PixelWatcher:
    def __init__(self, cfg, notify):
        self.cfg = cfg
        self.notify = notify
        self.enabled = False
        self.alive = True
        self.click_count = 0
        self.last_error = ""
        self._previous = None
        self._last_click = 0.0
        self._last_hotkey_state = False
        self._lock = threading.Lock()

    def point(self):
        width, height = pyautogui.size()
        x = max(0, min(width - 1, width // 2 + int(self.cfg["offset_x"])))
        y = max(0, min(height - 1, height // 2 + int(self.cfg["offset_y"])))
        return x, y

    @staticmethod
    def changed(a, b, tolerance):
        return any(abs(int(x) - int(y)) > tolerance for x, y in zip(a[:3], b[:3]))

    def set_enabled(self, value):
        with self._lock:
            self.enabled = bool(value)
            self._previous = None
        self.notify("state", self.enabled)

    def run(self):
        while self.alive:
            try:
                if keyboard.is_pressed(self.cfg["stop_key"]):
                    self.set_enabled(False)
                    time.sleep(0.25)
                    continue
                hotkey_down = keyboard.is_pressed(self.cfg["hotkey"])
                if hotkey_down and not self._last_hotkey_state:
                    self.set_enabled(not self.enabled)
                self._last_hotkey_state = hotkey_down

                if self.enabled:
                    pixel = pyautogui.pixel(*self.point())
                    if self._previous is None:
                        self._previous = pixel
                    elif self.changed(pixel, self._previous, int(self.cfg["tolerance"])):
                        now = time.monotonic()
                        if (now - self._last_click) * 1000 >= int(self.cfg["cooldown_ms"]):
                            pyautogui.click()
                            self.click_count += 1
                            self._last_click = now
                            self.notify("clicks", self.click_count)
                        self._previous = pixel
                else:
                    self._previous = None
                time.sleep(0.008)
            except Exception as exc:
                message = str(exc)
                if message != self.last_error:
                    self.last_error = message
                    self.notify("error", message)
                time.sleep(0.08)

    def stop(self):
        self.alive = False
        self.set_enabled(False)


class AsteriusApp(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.cfg = read_settings()
        self.theme = THEMES[self.cfg["theme"]]
        self.title(APP_NAME)
        self.geometry("430x650")
        self.minsize(400, 600)
        self.configure(fg_color=self.theme["bg"])
        self.attributes("-topmost", bool(self.cfg["always_on_top"]))
        try:
            self._icon_img = ImageTk.PhotoImage(load_logo(96))
            self.iconphoto(True, self._icon_img)
        except Exception:
            pass

        self.watcher = PixelWatcher(self.cfg, self.thread_message)
        self.worker = threading.Thread(target=self.watcher.run, daemon=True)
        self.worker.start()
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.build_ui()
        self.after(100, self.refresh_pixel)
        self.after(100, self.process_messages)

    def thread_message(self, kind, value):
        if not hasattr(self, "messages"):
            self.messages = []
        self.messages.append((kind, value))

    def process_messages(self):
        for kind, value in getattr(self, "messages", [])[:]:
            try:
                self.messages.remove((kind, value))
            except ValueError:
                pass
            if kind == "state":
                self.status.configure(text="АКТИВЕН" if value else "ОСТАНОВЛЕН", text_color=self.theme["accent"] if value else self.theme["muted"])
                self.start_button.configure(text="Остановить" if value else "Запустить")
            elif kind == "clicks":
                self.clicks_label.configure(text=str(value))
            elif kind == "error":
                self.status.configure(text="ОШИБКА: проверь разрешения", text_color="#ff657a")
        self.after(100, self.process_messages)

    def card(self, parent):
        frame = ctk.CTkFrame(parent, fg_color=self.theme["card"], corner_radius=16)
        frame.pack(fill="x", padx=18, pady=7)
        return frame

    def build_ui(self):
        t = self.theme
        header = ctk.CTkFrame(self, fg_color="transparent")
        header.pack(fill="x", padx=18, pady=(16, 8))
        logo = ImageTk.PhotoImage(load_logo(76))
        self.logo_image = logo
        ctk.CTkLabel(header, image=logo, text="").pack(side="left", padx=(0, 12))
        titles = ctk.CTkFrame(header, fg_color="transparent")
        titles.pack(side="left", fill="y", expand=True)
        ctk.CTkLabel(titles, text=APP_NAME, font=ctk.CTkFont(size=22, weight="bold"), text_color=t["text"]).pack(anchor="w", pady=(12, 0))
        ctk.CTkLabel(titles, text="Реакция на изменение цвета пикселя", font=ctk.CTkFont(size=11), text_color=t["muted"]).pack(anchor="w")

        status_card = self.card(self)
        ctk.CTkLabel(status_card, text="СОСТОЯНИЕ", text_color=t["muted"], font=ctk.CTkFont(size=11, weight="bold")).pack(anchor="w", padx=16, pady=(13, 2))
        self.status = ctk.CTkLabel(status_card, text="ОСТАНОВЛЕН", text_color=t["muted"], font=ctk.CTkFont(size=18, weight="bold"))
        self.status.pack(anchor="w", padx=16, pady=(0, 12))

        sample_card = self.card(self)
        ctk.CTkLabel(sample_card, text="ЦВЕТ В ЦЕНТРАЛЬНОЙ ТОЧКЕ", text_color=t["muted"], font=ctk.CTkFont(size=11, weight="bold")).pack(anchor="w", padx=16, pady=(12, 5))
        sample_row = ctk.CTkFrame(sample_card, fg_color="transparent")
        sample_row.pack(fill="x", padx=16, pady=(0, 13))
        self.swatch = ctk.CTkFrame(sample_row, width=38, height=38, fg_color="#000000", corner_radius=8)
        self.swatch.pack(side="left")
        self.rgb_label = ctk.CTkLabel(sample_row, text="RGB: —", text_color=t["text"], font=ctk.CTkFont(family="Consolas", size=13))
        self.rgb_label.pack(side="left", padx=12)

        stats = self.card(self)
        ctk.CTkLabel(stats, text="Количество кликов", text_color=t["muted"], font=ctk.CTkFont(size=12)).pack(side="left", padx=16, pady=14)
        self.clicks_label = ctk.CTkLabel(stats, text="0", text_color=t["text"], font=ctk.CTkFont(size=16, weight="bold"))
        self.clicks_label.pack(side="right", padx=16, pady=14)

        settings = self.card(self)
        self.add_slider(settings, "Допуск изменения RGB", "Чем выше значение, тем сильнее должно измениться цвет.", "tolerance", 0, 100)
        self.add_slider(settings, "Задержка между кликами (мс)", "Минимальный интервал между автоматическими кликами.", "cooldown_ms", 0, 1000)
        self.add_slider(settings, "Смещение X", "Сдвиг проверяемой точки по горизонтали.", "offset_x", -300, 300)
        self.add_slider(settings, "Смещение Y", "Сдвиг проверяемой точки по вертикали.", "offset_y", -300, 300)

        bottom = ctk.CTkFrame(self, fg_color="transparent")
        bottom.pack(fill="x", padx=18, pady=12)
        self.start_button = ctk.CTkButton(bottom, text="Запустить", height=46, fg_color=t["accent"], hover_color=t["track"], font=ctk.CTkFont(size=15, weight="bold"), command=self.toggle)
        self.start_button.pack(fill="x", pady=(0, 8))
        row = ctk.CTkFrame(bottom, fg_color="transparent")
        row.pack(fill="x")
        ctk.CTkLabel(row, text=f"Переключение: {self.cfg['hotkey'].upper()}   •   Стоп: ESC", text_color=t["muted"], font=ctk.CTkFont(size=11)).pack(side="left")
        ctk.CTkButton(row, text="Тема", width=76, height=28, fg_color=t["card"], hover_color=t["track"], command=self.next_theme).pack(side="right")

    def add_slider(self, parent, title, description, key, low, high):
        t = self.theme
        block = ctk.CTkFrame(parent, fg_color="transparent")
        block.pack(fill="x", padx=14, pady=(8, 4))
        top = ctk.CTkFrame(block, fg_color="transparent")
        top.pack(fill="x")
        ctk.CTkLabel(top, text=title, text_color=t["text"], font=ctk.CTkFont(size=12, weight="bold")).pack(side="left")
        value_label = ctk.CTkLabel(top, text=str(self.cfg[key]), text_color=t["accent"], font=ctk.CTkFont(size=12, weight="bold"))
        value_label.pack(side="right")
        ctk.CTkLabel(block, text=description, text_color=t["muted"], font=ctk.CTkFont(size=10), wraplength=360, justify="left").pack(anchor="w", pady=(1, 2))
        slider = ctk.CTkSlider(block, from_=low, to=high, number_of_steps=high-low, progress_color=t["accent"], button_color=t["accent"], command=lambda v: self.change_setting(key, int(round(v)), value_label))
        slider.set(self.cfg[key])
        slider.pack(fill="x", pady=(0, 5))

    def change_setting(self, key, value, label):
        self.cfg[key] = value
        label.configure(text=str(value))
        save_settings(self.cfg)

    def toggle(self):
        self.watcher.set_enabled(not self.watcher.enabled)

    def next_theme(self):
        names = list(THEMES)
        index = (names.index(self.cfg["theme"]) + 1) % len(names)
        self.cfg["theme"] = names[index]
        save_settings(self.cfg)
        messagebox.showinfo(APP_NAME, "Тема сохранена. Перезапусти приложение, чтобы применить её полностью.")

    def refresh_pixel(self):
        if self.winfo_exists():
            try:
                color = pyautogui.pixel(*self.watcher.point())
                self.swatch.configure(fg_color="#%02x%02x%02x" % color)
                self.rgb_label.configure(text=f"RGB: {color[0]}, {color[1]}, {color[2]}")
            except Exception:
                pass
            self.after(250, self.refresh_pixel)

    def close(self):
        self.watcher.stop()
        save_settings(self.cfg)
        self.destroy()


def main():
    parser = argparse.ArgumentParser(description=APP_NAME)
    parser.add_argument("--make-icon", action="store_true", help="Create asterius.ico from the embedded logo")
    args = parser.parse_args()
    if args.make_icon:
        make_icon()
        return
    app = AsteriusApp()
    app.mainloop()


if __name__ == "__main__":
    main()
